entries[12759] = { ["name"] = "Gnomentodesstrahl", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Instabiler Auslöser , Essenz des Untodes , Sekret des Untodes (4), Veredelter Mithrilzylinder\nWird beim Aufheben gebunden\nSchmuck\nBenutzen: Der Todesstrahl benötigt einige Zeit, um sich mit Eurer Lebenskraft aufzuladen und feuert dann einen Energiestoß auf Euren Gegner ab. (5 Min Abklingzeit)\n\"Verwendung dieses Geräts kann zum Tod oder zu schweren Verletzungen führen.\"" }
