entries[12897] = { ["name"] = "Gnomenschutzbrille", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFeuerschutzbrille , Mithrilrohr , Goldkraftkern (2), Schweres Leder (2)\nGnomenschutzbrille\nWird beim Aufheben gebunden\nKopf Stoff\n88 Rüstung\n+9 Ausdauer\n+9 Intelligenz\n+9 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst\n(210)" }
