entries[12899] = { ["name"] = "Gnomenschrumpfstrahl", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Instabiler Auslöser , Mithrilbarren (4), Jade (2)\nGnomenschrumpfstrahl\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(205)\nBenutzen: Lässt das Ziel schrumpfen und verringert seine Angriffskraft um 250. Zumindest ist das meistens der Fall... (5 Min Abklingzeit)" }
entries[12900] = { ["name"] = "Mobiler Alarm", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Instabiler Auslöser , Mithrilbarren (4)" }
entries[12902] = { ["name"] = "Gnomen-Net-o-Matik-Projektor", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr , Schattenseide (2), Dicke Spinnenseide (4), Robustes Sprengpulver (2), Mithrilbarren (4)\nGnomen-Net-o-Matik-Projektor\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(210)\nBenutzen: Hält das Ziel 20 Sek. lang in einem Netz fest. Das Netz ist allerdings mit einer Menge Haken bestückt und verfängt sich manchmal auch in der Kleidung des Benutzers, wenn es abgefeuert wird... (10 Min Abklingzeit)" }
entries[12903] = { ["name"] = "Gnomenunglücksverhinderungsgürtel", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwärzlicher Gürtel , Mithrilbarren (4), Echtsilberbarren (2), Instabiler Auslöser , Aquamarin (2)\nGnomenunglücksverhinderungsgürtel\nWird beim Anlegen gebunden\nTaille Leder\n95 Rüstung\n+6 Ausdauer\nHaltbarkeit 40 / 40\nBenötigt Ingenieurskunst\n(215)\nBenutzen: Ein Kraftfeldschild schützt Euch 10 Min. lang vor bis zu 500 Schaden.\nWARNUNG: Kraftfeld kann überladen werden, wenn es getroffen wird. Der Träger wird dann für gewisse Zeit aus dieser Dimension entfernt. (Procchance: 5%) (1 Stunde Abklingzeit)" }
entries[12904] = { ["name"] = "Gnomenamateurradio", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Mithrilbarren (2), Gyrochronatom , Instabiler Auslöser" }
entries[12905] = { ["name"] = "Gnomenraketenstiefel", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwarze Magiestoffstiefel , Mithrilrohr (2), Schweres Leder (4), Robustes Sprengpulver (8), Gyrochronatom (4)\nGnomenraketenstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n79 Rüstung\nHaltbarkeit 55 / 55\nBenötigt Ingenieurskunst\n(225)\nBenutzen: Diese Stiefel erhöhen Euer Lauftempo 20 Sek. lang erheblich. WARNUNG: Ihre Stromversorgung und Gyros funktionieren nicht immer so, wie sie eigentlich sollten. (15 Min Abklingzeit)" }
entries[12906] = { ["name"] = "Gnomenkampfhuhn", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilgehäuse , Echtsilberbarren (6), Mithrilbarren (6), Veredelter Mithrilzylinder (2), Goldkraftkern , Jade (2)\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(230)\nBenutzen: Erschafft ein Kampfhuhn, das 1.50 Min. lang oder bis es zerstört wird für Euch kämpft. (20 Min Abklingzeit)" }
