entries[13898] = { ["name"] = "Waffe - Feurige Waffe", ["text"] = "Wirken in 5 sek.\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nKleiner strahlender Splitter (4), Essenz des Feuers\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie oft zusätzlich 40 Feuerschaden verursacht." }
