entries[14514] = { ["name"] = "Blinzeln", ["text"] = "75 Mana\nSofort\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von jeglichen Fesseln." }
entries[14515] = { ["name"] = "Gedanken beherrschen", ["text"] = "30 Mana 20 Meter Reichweite\nWirken in 2 sek." }
entries[14516] = { ["name"] = "Stoß", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nSchlägt einen Feind und fügt erhöhten Nahkampfschaden zu." }
entries[14517] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFügt einem Gegner 60% des normalen Waffenschadens zu und erhöht seinen erlittenen Heiligschaden pro Anwendung von 'Kreuzfahrerstoß' um 10. Bis zu 5-mal stapelbar. Hält 15 Sek. lang an." }
entries[14518] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFügt einem Gegner 60% Waffenschaden zu und erhöht seinen erlittenen Heiligschaden pro Anwendung von 'Kreuzfahrerstoß'. Bis zu 5-mal stapelbar. Hält 15 Sek. lang an." }
entries[14520] = { ["name"] = "Mentale Beweglichkeit", ["text"] = "Verringert die Manakosten Eurer Spontanzauber um 4%." }
entries[14522] = { ["name"] = "Unbezwingbarer Wille", ["text"] = "Verringert die Dauer auf Euch wirkender Betäubungs-, Furcht- und Stilleeffekte um weitere 6%." }
entries[14523] = { ["name"] = "Abbitte", ["text"] = "Wenn Ihr mittels Eures Zaubers 'Heilige Pein' oder 'Heiliges Feuer' Schaden verursacht, wird sofort ein Verbündeter um 50% des verursachten Schadens geheilt, der sich innerhalb von 15 Metern um das Ziel befindet.\n\nWird der Zaubernde selbst durch 'Abbitte' geheilt, ist der Effekt des Zaubers halbiert." }
entries[14524] = { ["name"] = "Zauberstabspezialisierung", ["text"] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 15%." }
